}

/**
 * Build a fully-resolved profiles.yml for the `modeling` project.
 * We embed the PEM key as an inline block scalar so dbt-snowflake
 * can consume it directly via its `private_key` field instead of
 * `private_key_path`. That avoids writing the key to disk inside
 * the sandbox.
 */
function buildProfilesYaml(input: ProfilesInput): string {
  const keyLines = input.privateKeyPem
    .split("\n")
    .map((line) => `        ${line}`)
    .join("\n");

  return `modeling:
  target: prod
  outputs:
    prod:
      type: snowflake
      account: ${input.account}
      user: ${input.user}
      private_key: |
${keyLines}
      role: ${input.role}
      warehouse: ${input.warehouse}
      database: ${input.database}
      schema: ${input.schema}
      threads: 8
      client_session_keep_alive: false
`;
}

function shellQuote(arg: string): string {
  if (/^[a-zA-Z0-9._\-+/=:@,]+$/.test(arg)) return arg;
  return `'${arg.replace(/'/g, "'\\''")}'`;
}

function tail(text: string, maxChars: number): string {
  if (text.length <= maxChars) return text;
  return text.slice(text.length - maxChars);
}

